/**
 * Get tier icon SVG by tier key
 * @param {string} tierKey 
 * @returns {string|null}
 */
export function getTierIconSvg(tierKey) {
  if (tierKey === TIERS.HIRES.key) return TIER_ICONS.HIRES;
  if (tierKey === TIERS.STUDIO.key) return TIER_ICONS.STUDIO;
  if (tierKey === TIERS.LOSSLESS.key) return TIER_ICONS.LOSSLESS;
  if (tierKey === TIERS.LOSSY.key || tierKey === TIERS.LOSSY_HQ.key) return TIER_ICONS.LOSSY;
  return null;
}

/**
 * Render tier badge HTML with icon or text
 * @param {Object} tierInfo 
 * @param {Object} [options] 
 * @returns {string}
 */
export function renderTierBadge(tierInfo, options = {}) {
  if (!tierInfo) return '';
  const icon = getTierIconSvg(tierInfo.tier);
  const title = tierInfo.label || tierInfo.tier || '';
  const extraStyle = options.style ? ` style="${options.style}"` : '';
  const content = icon || title;
  return `<span class="badge ${tierInfo.badgeClass}" title="${title}" aria-label="${title}"${extraStyle}>${content}</span>`;
}

/**
 * Get numeric rank for a tier key (e.g. 'HI-RES' => 5)
 * @param {string} tierKey 
 * @returns {number}
 */
export function getTierRank(tierKey) {
  if (!tierKey) return 0;
  for (const t of Object.values(TIERS)) {
    if (t.key === tierKey) return t.rank;
  }
  return 0;
}

/**
 * Classify quality tier from streamInfo and file format
 * @param {Object} streamInfo 
 * @param {string} format 
 * @returns {{ tier: string, badgeClass: string, label: string, shortTag: string, details: string, iconSvg: string|null }}
 */
export function classifyQualityTier(streamInfo = {}, format = '') {
  const ext = (format || '').toLowerCase();
  const sr = streamInfo.sampleRate || 44100;
  const bits = streamInfo.bitsPerSample || 16;
  const codec = (streamInfo.codec || '').toUpperCase();
  const isLossless = ['FLAC', 'WAV', 'AIFF', 'ALAC', 'WV', 'APE'].some(
    fmt => ext.includes(fmt.toLowerCase()) || codec.includes(fmt)
  );

  // Helper for lossless format name
  const getLosslessFmt = () => {
    if (codec.includes('FLAC') || ext.includes('flac')) return 'FLAC';
    if (codec.includes('WAV') || ext.includes('wav')) return 'WAV';
    if (codec.includes('ALAC') || ext.includes('alac') || ext.includes('m4a')) return 'ALAC';
    if (codec.includes('AIFF') || ext.includes('aiff') || ext.includes('aif')) return 'AIFF';
    if (codec.includes('APE') || ext.includes('ape')) return 'APE';
    return codec || 'LOSSLESS';
  };

  // Helper for sample rate string (e.g. 96, 44.1, 88.2, 192)
  const getSrStr = () => {
    const khz = sr / 1000;
    return sr % 1000 === 0 ? khz.toFixed(0) : khz.toFixed(1);
  };

  // 1. DSD Tier
  if (ext.includes('dsf') || ext.includes('dff') || codec.includes('DSD') || sr >= 2822400) {
    let dsdRate = 'DSD64';
    if (sr >= 11289600) dsdRate = 'DSD256';
    else if (sr >= 5644800) dsdRate = 'DSD128';
    else if (sr >= 2822400) dsdRate = 'DSD64';
    else dsdRate = 'DSD';

    return {
      tier: TIERS.DSD.key,
      badgeClass: TIERS.DSD.badgeClass,
      label: TIERS.DSD.label,
      shortTag: dsdRate,
      details: `${(sr / 1000000).toFixed(2)} MHz • 1-bit DSD`,
      iconSvg: null
    };
  }

  // 2. Lossless Tiers
  if (isLossless) {
    const fmtName = getLosslessFmt();
    const srStr = getSrStr();
    const shortTag = `${fmtName} ${bits}/${srStr}`;

    if (bits >= 24 && sr >= 88200) {
      return {
        tier: TIERS.HIRES.key,
        badgeClass: TIERS.HIRES.badgeClass,
        label: TIERS.HIRES.label,
        shortTag,
        details: `${bits}-bit / ${(sr / 1000).toFixed(1)} kHz ${streamInfo.codec || 'Lossless'}`,
        iconSvg: TIER_ICONS.HIRES
      };
    }
    if (bits >= 24 && (sr === 44100 || sr === 48000)) {
      return {
        tier: TIERS.STUDIO.key,
        badgeClass: TIERS.STUDIO.badgeClass,
        label: TIERS.STUDIO.label,
        shortTag,
        details: `24-bit / ${(sr / 1000).toFixed(1)} kHz Studio Master`,
        iconSvg: TIER_ICONS.STUDIO
      };
    }
    return {
      tier: TIERS.LOSSLESS.key,
      badgeClass: TIERS.LOSSLESS.badgeClass,
      label: TIERS.LOSSLESS.label,
      shortTag,
      details: `16-bit / ${(sr / 1000).toFixed(1)} kHz (CD Quality)`,
      iconSvg: TIER_ICONS.LOSSLESS
    };
  }

  // 3. Lossy Tiers
  const bitrate = streamInfo.bitrate || 0;
  const kbps = Math.round(bitrate > 1000 ? bitrate / 1000 : bitrate);
  const getLossyFmt = () => {
    if (codec.includes('AAC') || ext.includes('aac') || ext.includes('m4a')) return 'AAC';
    if (codec.includes('OGG') || ext.includes('ogg')) return 'OGG';
    if (codec.includes('OPUS') || ext.includes('opus')) return 'OPUS';
    return 'MP3';
  };
  const lossyFmt = getLossyFmt();
  const lossyShortTag = kbps > 0 ? `${lossyFmt} ${kbps}k` : lossyFmt;

  if (bitrate >= 256) {
    return {
      tier: TIERS.LOSSY_HQ.key,
      badgeClass: TIERS.LOSSY_HQ.badgeClass,
      label: TIERS.LOSSY_HQ.label,
      shortTag: lossyShortTag,
      details: `${bitrate} kbps ${streamInfo.codec || 'Lossy'}`,
      iconSvg: TIER_ICONS.LOSSY
    };
  }
  return {
    tier: TIERS.LOSSY.key,
    badgeClass: TIERS.LOSSY.badgeClass,
    label: TIERS.LOSSY.label,
    shortTag: lossyShortTag,
    details: `${bitrate ? bitrate + ' kbps' : 'Standard'} Lossy`,
    iconSvg: TIER_ICONS.LOSSY
  };
}
